import  { MovieEnums} from  '@/constants/movieEnums';
import { create } from "zustand";
import { persist, createJSONStorage } from "zustand/middleware";

interface User {
  email: string;
  password?: string;
}

interface AuthState {
  registeredUsers: User[];
  currentUser: User | null;
  isAuthenticated: boolean;
  error: string | null;
  isRegistered: boolean;
  registerUser: (
    userData: User & {
      email: string;
      password: string;
      firstName: string;
      lastName: string;
      mobileNumber: string;
      confirmPassword: string;
      gender: string;
      acceptanceMessage:boolean | undefined;
    },
  ) => void;
  login: (credentials: { email: string; password: string }) => void;
  logout: () => void;
  clearError: () => void;
}
export const useAuthStore = create<AuthState>()(
  persist(
    (set, get) => ({
      registeredUsers: [],
      currentUser: null,
      isAuthenticated: false,
      error: null,
      isRegistered: false,
      registerUser: (userData) => {
        const { registeredUsers } = get();
        const exists = registeredUsers.find((u) => u.email === userData.email);
        if (exists) {
          set({ error: "User already exists!!", isRegistered: false });
        } else {
          set({
            registeredUsers: [...registeredUsers, userData],
            isRegistered: true,
            error: null,
          });
        }
      },

      login: (credentials) => {
        const { registeredUsers } = get();
        const userMatch = registeredUsers.find(
          (u) =>
            u.email === credentials.email && u.password === credentials.password,);
        if (userMatch) {
          set({
            currentUser: {email: userMatch.email},
            isAuthenticated: true,
            error: null,
          });
        } else {
          set({
            isAuthenticated: false,
            error: "Invalid credentials. Please register first.",
          });
        }
      },
      logout: () => {
        set({
          currentUser: null,
          isAuthenticated: false,
        });
      },
      clearError: () => set({ error: null }),
    }),
    {
      name: MovieEnums.AUTHREGISTER,
      storage: createJSONStorage(() => localStorage),
      partialize: (state) => ({
        registeredUsers: state.registeredUsers,
        currentUser: state.currentUser,
        isAuthenticated: state.isAuthenticated,
      }),
    },
  ),
);
